{
  "model": "openai/gpt-4o-mini",
  "input": "Using the attached knowledge, summarise it in one sentence.",
  "tools": [
    {
      "type": "file_search",
      "vector_store_ids": [
        "{{openaiVectorStoreId}}"
      ]
    }
  ],
  "tool_choice": "required",
  "include": [
    "file_search_call.results"
  ],
  "max_output_tokens": 256
}

{
  "model": "openai/sora-2",
  "prompt": "a red circle on a white background",
  "seconds": "4"
}

{
  "model": "vertex/veo-3.0-fast-generate-001",
  "prompt": "a red circle on a white background",
  "seconds": "4"
}

{
  "messages": [
    {
      "role": "user",
      "content": "What is in the index? One sentence."
    }
  ],
  "data_sources": [
    {
      "type": "azure_search",
      "parameters": {
        "endpoint": "{{azureSearchEndpoint}}",
        "index_name": "{{azureSearchIndex}}",
        "authentication": {
          "type": "api_key",
          "key": "{{azureSearchKey}}"
        }
      }
    }
  ],
  "max_tokens": 128
}

{
  "model": "azure/gpt-4o-audio-preview",
  "modalities": [
    "text"
  ],
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "In a few words, describe the sound in this clip."
        },
        {
          "type": "input_audio",
          "input_audio": {
            "data": "",
            "format": "wav"
          }
        }
      ]
    }
  ],
  "max_tokens": 64
}

{
  "model": "claude-haiku-4-5",
  "max_tokens": 512,
  "tools": [
    {
      "type": "web_fetch_20250910",
      "name": "web_fetch",
      "max_uses": 1
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "Fetch https://example.com and tell me its page title."
    }
  ]
}

{
  "model": "claude-haiku-4-5",
  "max_tokens": 512,
  "tools": [
    {
      "type": "web_fetch_20260309",
      "name": "web_fetch",
      "max_uses": 1
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "Fetch https://example.com and tell me its page title."
    }
  ]
}
